"""Fetch a pinned Bridge checkout and apply the L4D2 bridge patch."""
import argparse
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[1]
COMMIT = "9aa74f8dfad2188efbd0f717c64d9f8fa909787e"
REMOTE = "https://github.com/NVIDIAGameWorks/dxvk-remix.git"


def run(*args, cwd=None):
    subprocess.run(args, cwd=cwd, check=True)


def prepare(source):
    if not source.exists():
        source.parent.mkdir(parents=True, exist_ok=True)
        run("git", "init", str(source))
        run("git", "config", "core.autocrlf", "false", cwd=source)
        run("git", "remote", "add", "origin", REMOTE, cwd=source)
        run("git", "fetch", "--depth=1", "origin", COMMIT, cwd=source)
        run("git", "checkout", "--detach", "FETCH_HEAD", cwd=source)
    head = subprocess.check_output(
        ["git", "rev-parse", "HEAD"], cwd=source, text=True).strip()
    if head != COMMIT:
        raise RuntimeError(f"Expected upstream {COMMIT}, found {head}; checkout preserved")
    patch = ROOT / "patches" / "l4d2-bridge.patch"
    already_applied = subprocess.run(
        ["git", "apply", "--reverse", "--check", str(patch)],
        cwd=source, capture_output=True).returncode == 0
    if not already_applied:
        if subprocess.check_output(["git", "status", "--porcelain"], cwd=source):
            raise RuntimeError("Upstream checkout contains changes; refusing to overwrite")
        run("git", "apply", "--check", str(patch), cwd=source)
        run("git", "apply", str(patch), cwd=source)
    run("git", "submodule", "update", "--init", "--depth=1",
        "submodules/Detours", cwd=source)
    print(f"Prepared {source}; RTX renderer and NVIDIA GPU SDK submodules are not fetched")


if __name__ == "__main__":
    parser = argparse.ArgumentParser()
    parser.add_argument("--source", type=Path, default=ROOT / ".deps" / "dxvk-remix")
    prepare(parser.parse_args().source.resolve())
